            pSkillRecord != (D2SkillsTxt *)0x0)) &&
     ((pCorpse != (D2UnitStrc *)0x0 &&
      (nStatVal = D2Common::Skills::Skills::SKILLS_IsSelectableCorpse3(pCorpse), nStatVal != 0)))) {
