        return 0;
      }
    }
    nCalcVal = D2Common::Skills::Skills::D2GetSkillCalc
                         (pUnit,pSkillRecord->calc[1],eSkill,nSkillLvl);
    nMaxVal = D2Common::Stats::StatsEx::STATLIST_GetMaxLifeFromUnit(pUnit);
    nStatVal = D2Common::Stats::StatsEx::STATSEX_GetCurrentStat(pUnit,UNITSTAT_hitpoints,0);
    nStatVal = nStatVal + nCalcVal * 0x100;
    if (nMaxVal < nStatVal) {
      nStatVal = nMaxVal;
    }
    D2Common::Stats::StatsEx::STATLIST_SetUnitStat(pUnit,UNITSTAT_hitpoints,nStatVal,0);
    nCalcVal = D2Common::Skills::Skills::D2GetSkillCalc
                         (pUnit,pSkillRecord->calc[2],eSkill,nSkillLvl);
    nMaxVal = D2Common::Stats::StatsEx::STATLIST_GetMaxManaFromUnit(pUnit);
    nStatVal = D2Common::Stats::StatsEx::STATSEX_GetCurrentStat(pUnit,UNITSTAT_mana,0);
    nStatVal = nStatVal + nCalcVal * 0x100;
    if (nMaxVal < nStatVal) {
      nStatVal = nMaxVal;
    }
    D2Common::Stats::StatsEx::STATLIST_SetUnitStat(pUnit,UNITSTAT_mana,nStatVal,0);
    D2Common::DATATBLS::ItemStats::SetState(pCorpse,STATE_redeemed,1);
    pCorpse->eUnitFlags = pCorpse->eUnitFlags & ~(UNITFLAG_CANBEATTACKED|UNITFLAG_TARGETABLE);
    return 1;
  }
